import { HandlebarsContentEngine, } from '../content/content.engine';
import { ChannelTypeEnum, } from '../template/template.interface';
export class SmsHandler {
    message;
    provider;
    contentEngine;
    constructor(message, provider, contentEngine) {
        this.message = message;
        this.provider = provider;
        this.contentEngine = contentEngine ?? new HandlebarsContentEngine();
    }
    async send(data) {
        const attachments = data.$attachments?.filter((item) => item.channels?.length
            ? item.channels?.includes(ChannelTypeEnum.SMS)
            : true);
        let content = '';
        if (typeof this.message.template === 'string') {
            content = this.contentEngine.compileTemplate(this.message.template, data);
        }
        else {
            content = await this.message.template(data);
        }
        if (!data.$phone) {
            throw new Error('$phone is missing in trigger payload. To send an SMS You must specify a $phone property.');
        }
        return await this.provider.sendMessage({
            to: data.$phone,
            content,
            attachments,
        });
    }
}
